          "name": "Pull n8n Image",
          "type": "n8n-nodes-base.ssh",
          "position": [
            2512,
            672
          ],
          "typeVersion": 1
        },
        {
          "parameters": {
            "command": "sudo docker compose pull",
            "cwd": "={{ $('Set Default variable').item.json['working-directory'] }}"
          },
          "id": "e437f006-cdee-4ab3-bfaa-f323b072c380",
          "name": "docker compose pull",
          "type": "n8n-nodes-base.ssh",
