        "jsCode": "// Parse SSH output to get container info\nconst lxc = $('Split LXCs').item.json;\nconst sshOutput = $input.item.json.stdout || '';\n\nconst containers = [];\n\nfor (const line of sshOutput.split('\\n')) {\n  if (!line.trim()) continue;\n  \n  const [name, image] = line.split('|');\n  if (!name || !image) continue;\n  \n  // Parse image to get registry, repo, and tag\n  let registry = 'docker.io';\n  let repo = image;\n  let tag = 'latest';\n  \n  // Extract tag\n  if (repo.includes(':')) {\n    const parts = repo.split(':');\n    tag = parts.pop();\n    repo = parts.join(':');\n  }\n  \n  // Extract registry\n  if (repo.includes('/')) {\n    const firstPart = repo.split('/')[0];\n    if (firstPart.includes('.') || firstPart.includes(':')) {\n      registry = firstPart;\n      repo = repo.substring(firstPart.length + 1);\n    }\n  }\n  \n  // Normalize library images\n  if (registry === 'docker.io' && !repo.includes('/')) {\n    repo = 'library/' + repo;\n  }\n  \n  containers.push({\n    lxc_id: lxc.id,\n    lxc_name: lxc.name,\n    lxc_ip: lxc.ip,\n    container_name: name,\n    full_image: image,\n    registry: registry,\n    repository: repo,\n    current_tag: tag\n  });\n}\n\nreturn containers.map(c => ({ json: c }));"
