    },
    {
      "parameters": {},
      "id": "manual-trigger",
      "name": "Manual Trigger",
      "type": "n8n-nodes-base.manualTrigger",
      "position": [200, 300],
      "typeVersion": 1
    },
    {
      "parameters": {
        "assignments": {
          "assignments": [
            {
              "id": "lxcs",
              "name": "lxcs",
              "type": "array",
              "value": "={{ [\n  { \"id\": \"101\", \"name\": \"network-services\", \"ip\": \"10.100.1.101\" },\n  { \"id\": \"104\", \"name\": \"container-mgmt\", \"ip\": \"10.100.1.104\" },\n  { \"id\": \"200\", \"name\": \"traefik\", \"ip\": \"10.100.2.200\" },\n  { \"id\": \"201\", \"name\": \"dashboards\", \"ip\": \"10.100.2.201\" },\n  { \"id\": \"203\", \"name\": \"authentik\", \"ip\": \"10.100.2.203\" },\n  { \"id\": \"303\", \"name\": \"immich-importer\", \"ip\": \"10.100.3.103\" },\n  { \"id\": \"304\", \"name\": \"immich\", \"ip\": \"10.100.3.104\" },\n  { \"id\": \"401\", \"name\": \"jellyfin\", \"ip\": \"10.100.4.101\" },\n  { \"id\": \"402\", \"name\": \"media-management\", \"ip\": \"10.100.4.102\" },\n  { \"id\": \"500\", \"name\": \"monitoring\", \"ip\": \"10.100.5.100\" },\n  { \"id\": \"501\", \"name\": \"openwebui\", \"ip\": \"10.100.5.101\" },\n  { \"id\": \"502\", \"name\": \"n8n\", \"ip\": \"10.100.5.102\" },\n  { \"id\": \"503\", \"name\": \"obsidian-sync\", \"ip\": \"10.100.5.103\" },\n  { \"id\": \"504\", \"name\": \"documents\", \"ip\": \"10.100.5.104\" }\n] }}"
            },
            {
              "id": "ntfy_url",
              "name": "ntfy_url",
              "type": "string",
              "value": "http://10.100.5.100:8080/docker-updates"
            }
          ]
        },
        "options": {}
      },
      "id": "config",
      "name": "Configuration",
      "type": "n8n-nodes-base.set",
      "position": [400, 400],
      "typeVersion": 3.4
    },
    {
      "parameters": {
        "fieldToSplitOut": "lxcs",
        "options": {}
      },
      "id": "split-lxcs",
      "name": "Split LXCs",
      "type": "n8n-nodes-base.splitOut",
      "position": [600, 400],
      "typeVersion": 1
    },
    {
      "parameters": {
        "command": "docker ps --format '{{.Names}}|{{.Image}}' 2>/dev/null || echo ''",
        "cwd": "/config"
      },
      "id": "get-containers",
      "name": "Get Running Containers",
      "type": "n8n-nodes-base.ssh",
      "position": [800, 400],
      "typeVersion": 1,
      "credentials": {
        "sshPassword": {
          "id": "CREDENTIAL_ID",
          "name": "Proxmox Root SSH"
        }
      }
    },
    {
      "parameters": {
        "jsCode": "// Parse SSH output to get container info\nconst lxc = $('Split LXCs').item.json;\nconst sshOutput = $input.item.json.stdout || '';\n\nconst containers = [];\n\nfor (const line of sshOutput.split('\\n')) {\n  if (!line.trim()) continue;\n  \n  const [name, image] = line.split('|');\n  if (!name || !image) continue;\n  \n  // Parse image to get registry, repo, and tag\n  let registry = 'docker.io';\n  let repo = image;\n  let tag = 'latest';\n  \n  // Extract tag\n  if (repo.includes(':')) {\n    const parts = repo.split(':');\n    tag = parts.pop();\n    repo = parts.join(':');\n  }\n  \n  // Extract registry\n  if (repo.includes('/')) {\n    const firstPart = repo.split('/')[0];\n    if (firstPart.includes('.') || firstPart.includes(':')) {\n      registry = firstPart;\n      repo = repo.substring(firstPart.length + 1);\n    }\n  }\n  \n  // Normalize library images\n  if (registry === 'docker.io' && !repo.includes('/')) {\n    repo = 'library/' + repo;\n  }\n  \n  containers.push({\n    lxc_id: lxc.id,\n    lxc_name: lxc.name,\n    lxc_ip: lxc.ip,\n    container_name: name,\n    full_image: image,\n    registry: registry,\n    repository: repo,\n    current_tag: tag\n  });\n}\n\nreturn containers.map(c => ({ json: c }));"
      },
      "id": "parse-containers",
      "name": "Parse Container Info",
      "type": "n8n-nodes-base.code",
      "position": [1000, 400],
      "typeVersion": 2
    },
    {
      "parameters": {
        "jsCode": "// Build registry API URL for version check\nconst container = $input.item.json;\nlet apiUrl = '';\nlet releaseUrl = '';\nlet registryType = '';\n\nconst registry = container.registry;\nconst repo = container.repository;\nconst currentTag = container.current_tag;\n\n// Skip containers with SHA tags or 'latest' tag (can't compare)\nif (currentTag.startsWith('sha256:') || currentTag === 'latest') {\n  return [{ json: { ...container, skip: true, skip_reason: 'Cannot check version for tag: ' + currentTag } }];\n}\n\n// Determine registry type and build URLs\nif (registry === 'docker.io' || registry === 'docker.n8n.io') {\n  registryType = 'dockerhub';\n  const hubRepo = repo.startsWith('library/') ? repo.replace('library/', '') : repo;\n  apiUrl = `https://hub.docker.com/v2/repositories/${repo}/tags?page_size=100`;\n  releaseUrl = `https://hub.docker.com/r/${hubRepo}/tags`;\n} else if (registry === 'ghcr.io') {\n  registryType = 'ghcr';\n  // GitHub Container Registry - use GitHub API\n  const [owner, ...repoParts] = repo.split('/');\n  const repoName = repoParts.join('/');\n  apiUrl = `https://api.github.com/users/${owner}/packages/container/${repoName}/versions?per_page=50`;\n  releaseUrl = `https://github.com/${repo}/pkgs/container/${repoName}`;\n} else if (registry === 'lscr.io') {\n  registryType = 'lscr';\n  // LinuxServer.io - use GitHub releases\n  const repoName = repo.replace('linuxserver/', '');\n  apiUrl = `https://api.github.com/repos/linuxserver/docker-${repoName}/releases?per_page=20`;\n  releaseUrl = `https://github.com/linuxserver/docker-${repoName}/releases`;\n} else if (registry.includes('quay.io')) {\n  registryType = 'quay';\n  apiUrl = `https://quay.io/api/v1/repository/${repo}/tag/?limit=50`;\n  releaseUrl = `https://quay.io/repository/${repo}?tab=tags`;\n} else {\n  // Unknown registry\n  return [{ json: { ...container, skip: true, skip_reason: 'Unknown registry: ' + registry } }];\n}\n\nreturn [{ json: { ...container, apiUrl, releaseUrl, registryType } }];"
      },
      "id": "build-api-urls",
      "name": "Build Registry API URLs",
      "type": "n8n-nodes-base.code",
      "position": [1200, 400],
      "typeVersion": 2
    },
    {
      "parameters": {
        "conditions": {
          "options": { "version": 2, "caseSensitive": true, "typeValidation": "strict" },
          "combinator": "and",
          "conditions": [
            {
              "operator": { "type": "boolean", "operation": "notTrue" },
              "leftValue": "={{ $json.skip }}",
              "rightValue": ""
            }
          ]
        },
        "options": {}
      },
      "id": "filter-skipped",
      "name": "Filter Skipped",
      "type": "n8n-nodes-base.if",
      "position": [1400, 400],
      "typeVersion": 2.2
    },
    {
      "parameters": {
        "url": "={{ $json.apiUrl }}",
        "options": {
          "timeout": 10000
        }
      },
      "id": "fetch-registry",
      "name": "Fetch Registry Tags",
      "type": "n8n-nodes-base.httpRequest",
      "position": [1600, 300],
      "typeVersion": 4.2,
      "continueOnFail": true
    },
    {
      "parameters": {
        "jsCode": "// Parse registry response and find latest version\nconst container = $('Filter Skipped').item.json;\nconst response = $input.item.json;\nconst registryType = container.registryType;\nconst currentTag = container.current_tag;\n\nlet tags = [];\nlet latestTag = null;\n\n// Handle HTTP errors\nif (response.error || response.code) {\n  return [{ json: { \n    ...container, \n    error: true, \n    error_message: response.message || 'Failed to fetch tags',\n    update_available: false \n  }}];\n}\n\ntry {\n  if (registryType === 'dockerhub') {\n    // Docker Hub response\n    const results = response.results || [];\n    tags = results.map(t => t.name).filter(t => t && !t.includes('sha256'));\n  } else if (registryType === 'ghcr') {\n    // GitHub Container Registry\n    tags = (response || []).flatMap(v => {\n      const metadata = v.metadata?.container?.tags || [];\n      return metadata;\n    }).filter(t => t && !t.includes('sha256'));\n  } else if (registryType === 'lscr') {\n    // LinuxServer via GitHub Releases\n    tags = (response || []).map(r => r.tag_name).filter(t => t);\n  } else if (registryType === 'quay') {\n    // Quay.io\n    tags = (response.tags || []).map(t => t.name).filter(t => t && !t.includes('sha256'));\n  }\n} catch (e) {\n  return [{ json: { ...container, error: true, error_message: e.message, update_available: false }}];\n}\n\n// Filter to semver-like tags and find latest\nconst semverRegex = /^v?\\d+\\.\\d+(\\.\\d+)?(-[\\w.]+)?$/;\nconst semverTags = tags.filter(t => semverRegex.test(t));\n\n// Sort versions (simple semver sort)\nconst sortVersions = (a, b) => {\n  const parseVer = v => v.replace(/^v/, '').split(/[-.]/).map(p => parseInt(p) || 0);\n  const va = parseVer(a);\n  const vb = parseVer(b);\n  for (let i = 0; i < Math.max(va.length, vb.length); i++) {\n    if ((va[i] || 0) !== (vb[i] || 0)) return (vb[i] || 0) - (va[i] || 0);\n  }\n  return 0;\n};\n\nsemverTags.sort(sortVersions);\nlatestTag = semverTags[0] || null;\n\n// Compare versions\nconst normalizeVersion = v => v.replace(/^v/, '');\nconst currentNorm = normalizeVersion(currentTag);\nconst latestNorm = latestTag ? normalizeVersion(latestTag) : null;\n\nconst updateAvailable = latestNorm && currentNorm !== latestNorm && \n  sortVersions(currentTag, latestTag) > 0;\n\nreturn [{ json: {\n  ...container,\n  latest_tag: latestTag,\n  update_available: updateAvailable,\n  tags_found: semverTags.slice(0, 5)\n}}];"
      },
      "id": "parse-versions",
      "name": "Parse & Compare Versions",
      "type": "n8n-nodes-base.code",
      "position": [1800, 300],
      "typeVersion": 2
    },
    {
      "parameters": {
        "conditions": {
          "options": { "version": 2, "caseSensitive": true, "typeValidation": "strict" },
          "combinator": "and",
          "conditions": [
            {
              "operator": { "type": "boolean", "operation": "true" },
              "leftValue": "={{ $json.update_available }}",
              "rightValue": ""
            }
          ]
        },
        "options": {}
      },
      "id": "filter-updates",
      "name": "Has Updates?",
      "type": "n8n-nodes-base.if",
      "position": [2000, 300],
      "typeVersion": 2.2
    },
    {
      "parameters": {
        "aggregate": "aggregateAllItemData",
        "options": {}
      },
      "id": "aggregate-updates",
      "name": "Aggregate Updates",
      "type": "n8n-nodes-base.aggregate",
      "position": [2200, 200],
      "typeVersion": 1
    },
    {
      "parameters": {
        "jsCode": "// Build ntfy notification\nconst updates = $input.item.json.data || [];\nconst ntfyUrl = $('Configuration').item.json.ntfy_url;\n\nif (updates.length === 0) {\n  return [{ json: { skip: true, message: 'No updates found' }}];\n}\n\n// Group by LXC for cleaner output\nconst byLxc = {};\nfor (const u of updates) {\n  const key = `${u.lxc_id} (${u.lxc_name})`;\n  if (!byLxc[key]) byLxc[key] = [];\n  byLxc[key].push(u);\n}\n\n// Build message body\nlet body = `🐳 ${updates.length} Docker container update(s) available:\\n\\n`;\n\nfor (const [lxc, containers] of Object.entries(byLxc)) {\n  body += `📦 LXC ${lxc}:\\n`;\n  for (const c of containers) {\n    body += `  • ${c.container_name}\\n`;\n    body += `    ${c.current_tag} → ${c.latest_tag}\\n`;\n    body += `    ${c.releaseUrl}\\n\\n`;\n  }\n}\n\n// Build actions for first 3 updates\nconst actions = updates.slice(0, 3).map((u, i) => ({\n  action: 'view',\n  label: `${u.container_name}`,\n  url: u.releaseUrl\n}));\n\nreturn [{ json: {\n  ntfy_url: ntfyUrl,\n  title: `🐳 ${updates.length} Docker Updates Available`,\n  body: body,\n  priority: 3,\n  tags: ['whale', 'arrow_up'],\n  actions: actions\n}}];"
      },
      "id": "build-notification",
      "name": "Build ntfy Notification",
      "type": "n8n-nodes-base.code",
      "position": [2400, 200],
      "typeVersion": 2
    },
    {
      "parameters": {
        "conditions": {
          "options": { "version": 2, "caseSensitive": true, "typeValidation": "strict" },
          "combinator": "and",
          "conditions": [
            {
              "operator": { "type": "boolean", "operation": "notTrue" },
              "leftValue": "={{ $json.skip }}",
              "rightValue": ""
            }
          ]
        },
        "options": {}
      },
      "id": "filter-empty-notification",
      "name": "Has Notification?",
      "type": "n8n-nodes-base.if",
      "position": [2600, 200],
      "typeVersion": 2.2
    },
    {
      "parameters": {
        "method": "POST",
        "url": "={{ $json.ntfy_url }}",
        "sendHeaders": true,
        "headerParameters": {
          "parameters": [
            { "name": "Title", "value": "={{ $json.title }}" },
            { "name": "Priority", "value": "={{ $json.priority }}" },
            { "name": "Tags", "value": "={{ $json.tags.join(',') }}" },
            { "name": "Actions", "value": "={{ $json.actions.map(a => `view, ${a.label}, ${a.url}`).join('; ') }}" }
          ]
        },
        "sendBody": true,
        "bodyParameters": {
          "parameters": []
        },
        "specifyBody": "string",
        "body": "={{ $json.body }}",
        "options": {}
      },
      "id": "send-ntfy",
      "name": "Send ntfy Notification",
      "type": "n8n-nodes-base.httpRequest",
      "position": [2800, 100],
      "typeVersion": 4.2
    },
    {
      "parameters": {
        "content": "## Docker Container Update Checker\n\nThis workflow checks all homelab LXC containers for Docker image updates and sends notifications via ntfy.\n\n**Features:**\n- Checks Docker Hub, GHCR, and LinuxServer.io registries\n- Compares semantic versions\n- Sends actionable ntfy notifications with links to releases\n- Runs daily at 9 AM\n\n**Prerequisites:**\n1. SSH credential \"Proxmox Root SSH\" configured\n2. ntfy topic `docker-updates` exists",
        "height": 360,
