{
  "name": "Docker Container Update Checker",
  "nodes": [
    {
      "parameters": {
        "rule": {
          "interval": [{ "triggerAtHour": 9 }]
        }
      },
      "id": "schedule-trigger",
      "name": "Daily Check (9 AM)",
      "type": "n8n-nodes-base.scheduleTrigger",
      "position": [200, 500],
      "typeVersion": 1.2
    },
    {
      "parameters": {},
      "id": "manual-trigger",
      "name": "Manual Trigger",
      "type": "n8n-nodes-base.manualTrigger",
      "position": [200, 300],
      "typeVersion": 1
    },
    {
      "parameters": {
        "assignments": {
          "assignments": [
            {
              "id": "lxcs",
              "name": "lxcs",
              "type": "array",
              "value": "={{ [\n  { \"id\": \"101\", \"name\": \"network-services\" },\n  { \"id\": \"104\", \"name\": \"container-mgmt\" },\n  { \"id\": \"200\", \"name\": \"traefik\" },\n  { \"id\": \"201\", \"name\": \"dashboards\" },\n  { \"id\": \"203\", \"name\": \"authentik\" },\n  { \"id\": \"303\", \"name\": \"immich-importer\" },\n  { \"id\": \"304\", \"name\": \"immich\" },\n  { \"id\": \"401\", \"name\": \"jellyfin\" },\n  { \"id\": \"402\", \"name\": \"media-management\" },\n  { \"id\": \"500\", \"name\": \"monitoring\" },\n  { \"id\": \"501\", \"name\": \"openwebui\" },\n  { \"id\": \"502\", \"name\": \"n8n\" },\n  { \"id\": \"503\", \"name\": \"obsidian-sync\" },\n  { \"id\": \"504\", \"name\": \"documents\" }\n] }}"
            },
            {
              "id": "ntfy_url",
              "name": "ntfy_url",
              "type": "string",
              "value": "http://10.100.5.100:8080/docker-updates"
            },
            {
              "id": "proxmox_host",
              "name": "proxmox_host",
              "type": "string",
              "value": "10.100.0.1"
            }
          ]
        },
        "options": {}
      },
      "id": "config",
      "name": "Configuration",
      "type": "n8n-nodes-base.set",
      "position": [400, 400],
      "typeVersion": 3.4
    },
    {
      "parameters": {
        "fieldToSplitOut": "lxcs",
        "options": {}
      },
      "id": "split-lxcs",
      "name": "Split LXCs",
      "type": "n8n-nodes-base.splitOut",
      "position": [600, 400],
      "typeVersion": 1
    },
    {
      "parameters": {
        "command": "=pct exec {{ $json.id }} -- docker ps --format '{{.Names}}|{{.Image}}' 2>/dev/null || echo 'ERROR'",
        "cwd": "/"
      },
      "id": "get-containers",
      "name": "Get Running Containers",
      "type": "n8n-nodes-base.ssh",
      "position": [800, 400],
      "typeVersion": 1,
      "continueOnFail": true
    },
    {
      "parameters": {
        "jsCode": "const lxc = $('Split LXCs').item.json;\nconst sshOutput = $input.item.json.stdout || '';\n\nif (sshOutput.includes('ERROR') || !sshOutput.trim()) {\n  return [];\n}\n\nconst containers = [];\nfor (const line of sshOutput.split('\\n')) {\n  if (!line.trim()) continue;\n  const [name, image] = line.split('|');\n  if (!name || !image) continue;\n  \n  let registry = 'docker.io';\n  let repo = image;\n  let tag = 'latest';\n  \n  if (repo.includes(':')) {\n    const parts = repo.split(':');\n    tag = parts.pop();\n    repo = parts.join(':');\n  }\n  \n  if (repo.includes('/')) {\n    const firstPart = repo.split('/')[0];\n    if (firstPart.includes('.') || firstPart.includes(':')) {\n      registry = firstPart;\n      repo = repo.substring(firstPart.length + 1);\n    }\n  }\n  \n  if (registry === 'docker.io' && !repo.includes('/')) {\n    repo = 'library/' + repo;\n  }\n  \n  containers.push({\n    lxc_id: lxc.id,\n    lxc_name: lxc.name,\n    container_name: name,\n    full_image: image,\n    registry: registry,\n    repository: repo,\n    current_tag: tag\n  });\n}\n\nreturn containers.map(c => ({ json: c }));"
      },
      "id": "parse-containers",
      "name": "Parse Container Info",
      "type": "n8n-nodes-base.code",
      "position": [1000, 400],
      "typeVersion": 2
    },
    {
      "parameters": {
        "jsCode": "const container = $input.item.json;\nlet apiUrl = '';\nlet releaseUrl = '';\nlet registryType = '';\n\nconst registry = container.registry;\nconst repo = container.repository;\nconst currentTag = container.current_tag;\n\nif (currentTag.startsWith('sha256:') || currentTag === 'latest' || currentTag === '1' || currentTag === 'release') {\n  return [{ json: { ...container, skip: true, skip_reason: 'Non-semver tag: ' + currentTag } }];\n}\n\nif (registry === 'docker.io' || registry === 'docker.n8n.io') {\n  registryType = 'dockerhub';\n  const hubRepo = repo.startsWith('library/') ? repo.replace('library/', '') : repo;\n  apiUrl = `https://hub.docker.com/v2/repositories/${repo}/tags?page_size=100`;\n  releaseUrl = `https://hub.docker.com/r/${hubRepo}/tags`;\n} else if (registry === 'ghcr.io') {\n  registryType = 'ghcr';\n  const [owner, ...repoParts] = repo.split('/');\n  const repoName = repoParts.join('/');\n  apiUrl = `https://api.github.com/users/${owner}/packages/container/${repoName}/versions?per_page=50`;\n  releaseUrl = `https://github.com/${repo}/pkgs/container/${repoName}`;\n} else if (registry === 'lscr.io') {\n  registryType = 'lscr';\n  const repoName = repo.replace('linuxserver/', '');\n  apiUrl = `https://api.github.com/repos/linuxserver/docker-${repoName}/releases?per_page=20`;\n  releaseUrl = `https://github.com/linuxserver/docker-${repoName}/releases`;\n} else {\n  return [{ json: { ...container, skip: true, skip_reason: 'Unknown registry: ' + registry } }];\n}\n\nreturn [{ json: { ...container, apiUrl, releaseUrl, registryType } }];"
      },
      "id": "build-api-urls",
      "name": "Build Registry API URLs",
      "type": "n8n-nodes-base.code",
      "position": [1200, 400],
      "typeVersion": 2
    },
    {
      "parameters": {
        "conditions": {
          "options": { "version": 2, "caseSensitive": true, "typeValidation": "strict" },
          "combinator": "and",
          "conditions": [
            {
              "operator": { "type": "boolean", "operation": "notTrue" },
              "leftValue": "={{ $json.skip }}",
              "rightValue": ""
            }
          ]
        },
        "options": {}
      },
      "id": "filter-skipped",
      "name": "Filter Skipped",
      "type": "n8n-nodes-base.if",
      "position": [1400, 400],
      "typeVersion": 2.2
    },
    {
      "parameters": {
        "url": "={{ $json.apiUrl }}",
        "options": { "timeout": 15000 }
      },
      "id": "fetch-registry",
      "name": "Fetch Registry Tags",
      "type": "n8n-nodes-base.httpRequest",
      "position": [1600, 300],
      "typeVersion": 4.2,
      "continueOnFail": true
    },
    {
      "parameters": {
        "jsCode": "const container = $('Filter Skipped').item.json;\nconst response = $input.item.json;\nconst registryType = container.registryType;\nconst currentTag = container.current_tag;\n\nlet tags = [];\n\nif (response.error || response.code) {\n  return [{ json: { ...container, error: true, error_message: response.message || 'Failed to fetch', update_available: false }}];\n}\n\ntry {\n  if (registryType === 'dockerhub') {\n    tags = (response.results || []).map(t => t.name).filter(t => t && !t.includes('sha256'));\n  } else if (registryType === 'ghcr') {\n    tags = (response || []).flatMap(v => v.metadata?.container?.tags || []).filter(t => t && !t.includes('sha256'));\n  } else if (registryType === 'lscr') {\n    tags = (response || []).map(r => r.tag_name).filter(t => t);\n  }\n} catch (e) {\n  return [{ json: { ...container, error: true, error_message: e.message, update_available: false }}];\n}\n\nconst semverRegex = /^v?\\d+\\.\\d+(\\.\\d+)?(-[\\w.]+)?$/;\nconst semverTags = tags.filter(t => semverRegex.test(t));\n\nconst sortVersions = (a, b) => {\n  const parseVer = v => v.replace(/^v/, '').split(/[-.]/).map(p => parseInt(p) || 0);\n  const va = parseVer(a);\n  const vb = parseVer(b);\n  for (let i = 0; i < Math.max(va.length, vb.length); i++) {\n    if ((va[i] || 0) !== (vb[i] || 0)) return (vb[i] || 0) - (va[i] || 0);\n  }\n  return 0;\n};\n\nsemverTags.sort(sortVersions);\nconst latestTag = semverTags[0] || null;\n\nconst normalizeVersion = v => v.replace(/^v/, '');\nconst updateAvailable = latestTag && \n  normalizeVersion(currentTag) !== normalizeVersion(latestTag) && \n  sortVersions(currentTag, latestTag) > 0;\n\nreturn [{ json: { ...container, latest_tag: latestTag, update_available: updateAvailable }}];"
      },
      "id": "parse-versions",
      "name": "Parse & Compare Versions",
      "type": "n8n-nodes-base.code",
      "position": [1800, 300],
      "typeVersion": 2
    },
    {
      "parameters": {
        "conditions": {
          "options": { "version": 2, "caseSensitive": true, "typeValidation": "strict" },
          "combinator": "and",
          "conditions": [
            {
              "operator": { "type": "boolean", "operation": "true" },
              "leftValue": "={{ $json.update_available }}",
              "rightValue": ""
            }
          ]
        },
        "options": {}
      },
      "id": "filter-updates",
      "name": "Has Updates?",
      "type": "n8n-nodes-base.if",
      "position": [2000, 300],
      "typeVersion": 2.2
    },
    {
      "parameters": {
        "aggregate": "aggregateAllItemData",
        "options": {}
      },
      "id": "aggregate-updates",
      "name": "Aggregate Updates",
      "type": "n8n-nodes-base.aggregate",
      "position": [2200, 200],
      "typeVersion": 1
    },
    {
      "parameters": {
        "jsCode": "const updates = $input.item.json.data || [];\nconst ntfyUrl = $('Configuration').item.json.ntfy_url;\n\nif (updates.length === 0) {\n  return [{ json: { skip: true, message: 'No updates found' }}];\n}\n\nconst byLxc = {};\nfor (const u of updates) {\n  const key = `${u.lxc_id} (${u.lxc_name})`;\n  if (!byLxc[key]) byLxc[key] = [];\n  byLxc[key].push(u);\n}\n\nlet body = `${updates.length} Docker container update(s) available:\\n\\n`;\n\nfor (const [lxc, containers] of Object.entries(byLxc)) {\n  body += `LXC ${lxc}:\\n`;\n  for (const c of containers) {\n    body += `• ${c.container_name}: ${c.current_tag} → ${c.latest_tag}\\n  ${c.releaseUrl}\\n\\n`;\n  }\n}\n\nconst actions = updates.slice(0, 3).map(u => ({\n  action: 'view',\n  label: u.container_name.substring(0, 20),\n  url: u.releaseUrl\n}));\n\nreturn [{ json: {\n  ntfy_url: ntfyUrl,\n  title: `${updates.length} Docker Updates Available`,\n  body: body,\n  priority: 3,\n  tags: ['whale', 'arrow_up'],\n  actions: actions\n}}];"
      },
      "id": "build-notification",
      "name": "Build ntfy Notification",
      "type": "n8n-nodes-base.code",
      "position": [2400, 200],
      "typeVersion": 2
    },
    {
      "parameters": {
        "conditions": {
          "options": { "version": 2, "caseSensitive": true, "typeValidation": "strict" },
          "combinator": "and",
          "conditions": [
            {
              "operator": { "type": "boolean", "operation": "notTrue" },
              "leftValue": "={{ $json.skip }}",
              "rightValue": ""
            }
          ]
        },
        "options": {}
      },
      "id": "filter-empty-notification",
      "name": "Has Notification?",
      "type": "n8n-nodes-base.if",
      "position": [2600, 200],
      "typeVersion": 2.2
    },
    {
      "parameters": {
        "method": "POST",
        "url": "={{ $json.ntfy_url }}",
        "sendHeaders": true,
        "headerParameters": {
          "parameters": [
            { "name": "Title", "value": "={{ $json.title }}" },
            { "name": "Priority", "value": "={{ $json.priority }}" },
            { "name": "Tags", "value": "={{ $json.tags.join(',') }}" },
            { "name": "Actions", "value": "={{ $json.actions.map(a => `view, ${a.label}, ${a.url}`).join('; ') }}" }
          ]
        },
        "sendBody": true,
        "specifyBody": "string",
        "body": "={{ $json.body }}",
        "options": {}
      },
      "id": "send-ntfy",
      "name": "Send ntfy Notification",
      "type": "n8n-nodes-base.httpRequest",
      "position": [2800, 100],
      "typeVersion": 4.2
    },
    {
      "parameters": {
        "content": "## Docker Container Update Checker\n\nThis workflow checks all homelab LXC containers for Docker image updates and sends notifications via ntfy.\n\n**Features:**\n- Checks Docker Hub, GHCR, and LinuxServer.io registries\n- Compares semantic versions\n- Sends actionable ntfy notifications with links to releases\n- Runs daily at 9 AM\n\n**Prerequisites:**\n1. SSH credential configured for Proxmox host (10.100.0.1)\n2. The SSH node must use this credential\n\n**Setup:**\n1. Create SSH credential: Settings → Credentials → Add → SSH Password\n   - Name: Proxmox SSH\n   - Host: 10.100.0.1\n   - User: root\n   - Password: <your proxmox root password>\n2. Edit the 'Get Running Containers' SSH node and select the credential",
        "height": 480,
        "width": 360
      },
      "id": "sticky-header",
      "name": "Setup Instructions",
      "type": "n8n-nodes-base.stickyNote",
      "position": [180, 20],
      "typeVersion": 1
    }
  ],
  "connections": {
    "Daily Check (9 AM)": {
      "main": [[{ "node": "Configuration", "type": "main", "index": 0 }]]
    },
    "Manual Trigger": {
      "main": [[{ "node": "Configuration", "type": "main", "index": 0 }]]
    },
    "Configuration": {
      "main": [[{ "node": "Split LXCs", "type": "main", "index": 0 }]]
    },
    "Split LXCs": {
      "main": [[{ "node": "Get Running Containers", "type": "main", "index": 0 }]]
    },
    "Get Running Containers": {
      "main": [[{ "node": "Parse Container Info", "type": "main", "index": 0 }]]
    },
    "Parse Container Info": {
      "main": [[{ "node": "Build Registry API URLs", "type": "main", "index": 0 }]]
    },
    "Build Registry API URLs": {
      "main": [[{ "node": "Filter Skipped", "type": "main", "index": 0 }]]
    },
    "Filter Skipped": {
      "main": [
        [{ "node": "Fetch Registry Tags", "type": "main", "index": 0 }],
        []
      ]
    },
    "Fetch Registry Tags": {
      "main": [[{ "node": "Parse & Compare Versions", "type": "main", "index": 0 }]]
    },
    "Parse & Compare Versions": {
      "main": [[{ "node": "Has Updates?", "type": "main", "index": 0 }]]
    },
    "Has Updates?": {
      "main": [
        [{ "node": "Aggregate Updates", "type": "main", "index": 0 }],
        []
      ]
    },
    "Aggregate Updates": {
      "main": [[{ "node": "Build ntfy Notification", "type": "main", "index": 0 }]]
