    {
      "parameters": {
        "jsCode": "const lxc = $('Split LXCs').item.json;\nconst sshOutput = $input.item.json.stdout || '';\n\nif (sshOutput.includes('ERROR') || !sshOutput.trim()) {\n  return [];\n}\n\nconst containers = [];\nfor (const line of sshOutput.split('\\n')) {\n  if (!line.trim() || !line.startsWith('CONTAINER_INFO:')) continue;\n  const info = line.replace('CONTAINER_INFO:', '');\n  const [name, image] = info.split('|');\n  if (!name || !image) continue;\n  \n  // Remove leading / from container name\n  const cleanName = name.startsWith('/') ? name.substring(1) : name;\n  \n  let registry = 'docker.io';\n  let repo = image;\n  let tag = 'latest';\n  \n  if (repo.includes(':')) {\n    const parts = repo.split(':');\n    tag = parts.pop();\n    repo = parts.join(':');\n  }\n  \n  if (repo.includes('/')) {\n    const firstPart = repo.split('/')[0];\n    if (firstPart.includes('.') || firstPart.includes(':')) {\n      registry = firstPart;\n      repo = repo.substring(firstPart.length + 1);\n    }\n  }\n  \n  if (registry === 'docker.io' && !repo.includes('/')) {\n    repo = 'library/' + repo;\n  }\n  \n  containers.push({\n    lxc_id: lxc.id,\n    lxc_name: lxc.name,\n    container_name: cleanName,\n    full_image: image,\n    registry: registry,\n    repository: repo,\n    current_tag: tag\n  });\n}\n\nreturn containers.map(c => ({ json: c }));"
