      "type": "n8n-nodes-base.if",
      "position": [2000, 300],
      "typeVersion": 2.2
    },
    {
      "parameters": {
        "aggregate": "aggregateAllItemData",
        "options": {}
      },
      "id": "aggregate-updates",
      "name": "Aggregate Updates",
      "type": "n8n-nodes-base.aggregate",
      "position": [2200, 200],
      "typeVersion": 1
    },
    {
      "parameters": {
        "jsCode": "const updates = $input.item.json.data || [];\nconst ntfyUrl = $('Configuration').item.json.ntfy_url;\n\nif (updates.length === 0) {\n  return [{ json: { skip: true, message: 'No updates found' }}];\n}\n\nconst byLxc = {};\nfor (const u of updates) {\n  const key = `${u.lxc_id} (${u.lxc_name})`;\n  if (!byLxc[key]) byLxc[key] = [];\n  byLxc[key].push(u);\n}\n\nlet body = `${updates.length} Docker container update(s) available:\\n\\n`;\n\nfor (const [lxc, containers] of Object.entries(byLxc)) {\n  body += `LXC ${lxc}:\\n`;\n  for (const c of containers) {\n    const versionLabel = c.latest_is_prerelease ? ' [PRE-RELEASE]' : '';\n    body += `• ${c.container_name}: ${c.current_tag} → ${c.latest_tag}${versionLabel}\\n  ${c.releaseUrl}\\n\\n`;\n  }\n}\n\nconst actions = updates.slice(0, 3).map(u => ({\n  action: 'view',\n  label: u.container_name.substring(0, 20),\n  url: u.releaseUrl\n}));\n\nconst prereleaseCount = updates.filter(u => u.latest_is_prerelease).length;\nconst stableCount = updates.length - prereleaseCount;\nlet title = `${updates.length} Docker Updates Available`;\nif (prereleaseCount > 0 && stableCount > 0) {\n  title = `${stableCount} Stable + ${prereleaseCount} Pre-release Updates`;\n}\n\nreturn [{ json: {\n  ntfy_url: ntfyUrl,\n  title: title,\n  body: body,\n  priority: 3,\n  tags: ['whale', 'arrow_up'],\n  actions: actions\n}}];"
      },
