# Create the updated workflow with the simpler approach
cat /tmp/workflow.json | jq '
# Update the SSH node to use docker ps --format json (simple, no templates)
.nodes = [.nodes[] | 
  if .name == "Get Running Containers" then
    .parameters.command = "=pct exec {{ $json.id }} -- docker ps --format json 2>/dev/null || echo "{}""
  else
    .
  end
] |

# Update the Parse Container Info code node to handle JSON lines
.nodes = [.nodes[] |
  if .name == "Parse Container Info" then
    .parameters.jsCode = "// Parse docker ps JSON output (one JSON object per line)
const stdout = $input.first().json.stdout || "";
const lxcId = $input.first().json.id;
const lxcName = $input.first().json.name;

const containers = [];

// Each line is a separate JSON object
for (const line of stdout.split("\n")) {
  if (!line.trim() || line === "{}") continue;

  try {
    const container = JSON.parse(line);
    const name = container.Names || "";
    const image = container.Image || "";

    if (name && image) {
      containers.push({
        json: {
          lxcId,
          lxcName,
          containerName: name,
          image: image
        }
      });
    }
  } catch (e) {
    // Skip malformed lines
  }
}

// If no containers found, return empty indicator
if (containers.length === 0) {
  return [{ json: { lxcId, lxcName, containerName: null, image: null, skip: true } }];
}

return containers;"
  else
    .
  end
]
' > /tmp/workflow_updated.json

# Verify the changes
cat /tmp/workflow_updated.json | jq '.nodes[] | select(.name == "Get Running Containers") | .parameters.command'

