input.command:
python3 << 'PYEOF'
import json

# Load the workflow
with open('/tmp/workflow.json', 'r') as f:
    workflow = json.load(f)

# Update the SSH node command - simple docker ps --format json
for node in workflow['nodes']:
    if node['name'] == 'Get Running Containers':
        node['parameters']['command'] = '=pct exec {{ $json.id }} -- docker ps --format json 2>/dev/null || echo ""'
        print(f"Updated SSH node command")

# Update the Parse Container Info code
parse_code = '''// Parse docker ps JSON output (one JSON object per line)
const stdout = $input.first().json.stdout || "";
const lxcId = $input.first().json.id;
const lxcName = $input.first().json.name;

const containers = [];

// Each line is a separate JSON object
for (const line of stdout.split("\\n")) {
  if (!line.trim() || line === "{}") continue;

  try {
    const container = JSON.parse(line);
    const name = container.Names || "";
    const image = container.Image || "";

    if (name && image) {
      containers.push({
        json: {
          lxcId,
          lxcName,
          containerName: name,
          image: image
        }
      });
    }
  } catch (e) {
    // Skip malformed lines
  }
}

// If no containers found, return empty indicator
if (containers.length === 0) {
  return [{ json: { lxcId, lxcName, containerName: null, image: null, skip: true } }];
}

return containers;'''

for node in workflow['nodes']:
    if node['name'] == 'Parse Container Info':
        node['parameters']['jsCode'] = parse_code
        print(f"Updated Parse Container Info code")

# Save the updated workflow
with open('/tmp/workflow_updated.json', 'w') as f:
    json.dump(workflow, f, indent=2)

print("Workflow updated successfully")
PYEOF

