function parseImage(image) {
  let registry = 'docker.io';
  let repository = image;
  let tag = 'latest';

  // Extract tag if present
  const tagMatch = repository.match(/^(.+):([^:]+)$/);
  if (tagMatch) {
    repository = tagMatch[1];
    tag = tagMatch[2];
  }

  // Check for registry prefix
  if (repository.includes('/')) {
    const firstPart = repository.split('/')[0];
    // If first part has a dot or colon, it's a registry
    if (firstPart.includes('.') || firstPart.includes(':')) {
      registry = firstPart;
      repository = repository.substring(firstPart.length + 1);
    }
  }

  // Handle Docker Hub official images (no slash = library/image)
  if (!repository.includes('/') && registry === 'docker.io') {
    repository = 'library/' + repository;
  }

  return { registry, repository, current_tag: tag };
}

// Each line is a separate JSON object
for (const line of stdout.split("\\n")) {
  if (!line.trim() || line === "{}") continue;

  try {
    const container = JSON.parse(line);
    const name = container.Names || "";
    const image = container.Image || "";

    if (name && image) {
      const parsed = parseImage(image);
      containers.push({
        json: {
          lxcId,
          lxcName,
          containerName: name,
          image: image,
          ...parsed
        }
      });
    }
  } catch (e) {
    // Skip malformed lines
  }
}

// If no containers found, return empty indicator
if (containers.length === 0) {
  return [{ json: { lxcId, lxcName, containerName: null, image: null, skip: true } }];
}

return containers;'''

