# Update Parse Container Info to deduplicate images
parse_code = '''// Parse docker ps JSON output from ALL LXCs and deduplicate by image
const allContainers = [];
const seenImages = new Set();

// Parse image string into registry, repository, and tag
function parseImage(image) {
  let registry = 'docker.io';
  let repository = image;
  let tag = 'latest';

  // Extract tag if present
  const tagMatch = repository.match(/^(.+):([^:]+)$/);
  if (tagMatch) {
    repository = tagMatch[1];
    tag = tagMatch[2];
  }

  // Check for registry prefix
  if (repository.includes('/')) {
    const firstPart = repository.split('/')[0];
    // If first part has a dot or colon, it's a registry
    if (firstPart.includes('.') || firstPart.includes(':')) {
      registry = firstPart;
      repository = repository.substring(firstPart.length + 1);
    }
  }

  // Handle Docker Hub official images (no slash = library/image)
  if (!repository.includes('/') && registry === 'docker.io') {
    repository = 'library/' + repository;
  }

  return { registry, repository, current_tag: tag };
}

// Process each LXC's output
for (const item of $input.all()) {
  const stdout = item.json.stdout || "";
  const lxcId = item.json.id;
  const lxcName = item.json.name;

  // Each line is a separate JSON object
  for (const line of stdout.split("\\n")) {
    if (!line.trim() || line === "{}") continue;

    try {
      const container = JSON.parse(line);
      const name = container.Names || "";
      const image = container.Image || "";

      if (name && image) {
        // Deduplicate by image (not container name)
        if (seenImages.has(image)) {
          continue;  // Skip duplicate images
        }
        seenImages.add(image);

        const parsed = parseImage(image);
        allContainers.push({
          json: {
            lxcId,
            lxcName,
            containerName: name,
            image: image,
            ...parsed
          }
        });
      }
    } catch (e) {
      // Skip malformed lines
    }
  }
}

// If no containers found at all, return empty indicator
if (allContainers.length === 0) {
  return [{ json: { skip: true, skip_reason: 'No containers found' } }];
}

return allContainers;'''

for node in workflow['nodes']:
    if node['name'] == 'Parse Container Info':
        node['parameters']['jsCode'] = parse_code
        print("Updated Parse Container Info with deduplication")

