content.content:
const container = $('Filter Skipped').item.json;
const response = $input.item.json;
const registryType = container.registryType;
const currentTag = container.current_tag;
const includePrerelease = $('Configuration').item.json.include_prerelease;

let tags = [];

if (response.error || response.code) {
  return [{ json: { ...container, error: true, error_message: response.message || 'Failed to fetch', update_available: false }}];
}

try {
  if (registryType === 'dockerhub') {
    tags = (response.results || []).map(t => t.name).filter(t => t && !t.includes('sha256'));
  } else if (registryType === 'ghcr') {
    tags = (response || []).flatMap(v => v.metadata?.container?.tags || []).filter(t => t && !t.includes('sha256'));
  } else if (registryType === 'lscr') {
    const releases = response || [];
    tags = releases
      .filter(r => includePrerelease || !r.prerelease)
      .map(r => r.tag_name)
      .filter(t => t);
  }
} catch (e) {
  return [{ json: { ...container, error: true, error_message: e.message, update_available: false }}];
}

const prereleasePatterns = /-(alpha|beta|rc|dev|preview|canary|nightly|snapshot|test|unstable|exp|next)/i;
const currentIsPrerelease = prereleasePatterns.test(currentTag);

const semverRegex = /^v?\d+\.\d+(\.\d+)?(-[\w.]+)?$/;
let filteredTags = tags.filter(t => semverRegex.test(t));

if (!currentIsPrerelease && !includePrerelease) {
  filteredTags = filteredTags.filter(t => !prereleasePatterns.test(t));
}

const sortVersions = (a, b) => {
  const parseVer = v => v.replace(/^v/, '').split(/[-.]/).map(p => parseInt(p) || 0);
  const va = parseVer(a);
  const vb = parseVer(b);
  for (let i = 0; i < Math.max(va.length, vb.length); i++) {
    if ((va[i] || 0) !== (vb[i] || 0)) return (vb[i] || 0) - (va[i] || 0);
  }
  return 0;
};

filteredTags.sort(sortVersions);
const latestTag = filteredTags[0] || null;

const normalizeVersion = v => v.replace(/^v/, '');
const updateAvailable = latestTag && 
  normalizeVersion(currentTag) !== normalizeVersion(latestTag) && 
  sortVersions(currentTag, latestTag) > 0;

const latestIsPrerelease = latestTag ? prereleasePatterns.test(latestTag) : false;

return [{ json: { 
  ...container, 
  latest_tag: latestTag, 
  update_available: updateAvailable,
  current_is_prerelease: currentIsPrerelease,
  latest_is_prerelease: latestIsPrerelease,
  version_type: latestIsPrerelease ? 'pre-release' : 'stable'
}}];

