const results = [];

for (const item of $input.all()) {
  const container = item.json;

  // Skip if already marked for skip
  if (container.skip) {
    results.push({ json: { ...container } });
    continue;
  }

  let apiUrl = '';
  let releaseUrl = '';
  let registryType = '';

  const registry = container.registry || '';
  const repo = container.repository || '';
  const currentTag = container.current_tag || '';

  // Only skip sha256 digests - we can still check latest/release tags
  if (!currentTag || currentTag.startsWith('sha256:')) {
    results.push({ json: { ...container, skip: true, skip_reason: 'SHA256 digest or empty tag' } });
    continue;
  }

  if (registry === 'docker.io' || registry === 'docker.n8n.io') {
    registryType = 'dockerhub';
    const hubRepo = repo.startsWith('library/') ? repo.replace('library/', '') : repo;
    apiUrl = `https://hub.docker.com/v2/repositories/${repo}/tags?page_size=100`;
    releaseUrl = `https://hub.docker.com/r/${hubRepo}/tags`;
  } else if (registry === 'ghcr.io') {
    registryType = 'ghcr';
    const [owner, ...repoParts] = repo.split('/');
    const repoName = repoParts.join('/');
    apiUrl = `https://api.github.com/users/${owner}/packages/container/${repoName}/versions?per_page=50`;
    releaseUrl = `https://github.com/${repo}/pkgs/container/${repoName}`;
  } else if (registry === 'lscr.io') {
    registryType = 'lscr';
    const repoName = repo.replace('linuxserver/', '');
    apiUrl = `https://api.github.com/repos/linuxserver/docker-${repoName}/releases?per_page=20`;
    releaseUrl = `https://github.com/linuxserver/docker-${repoName}/releases`;
  } else {
    results.push({ json: { ...container, skip: true, skip_reason: 'Unknown registry: ' + registry } });
    continue;
  }

  results.push({ json: { ...container, apiUrl, releaseUrl, registryType } });
}

return results;'''

